    return [(s[i:] + s[:i]) for i in range(n)]

def get_count(n, s):
    s = s.lower()
    binary_chars = 2  # assuming the character set is limited to '0' and '1'
    length_s = len(s)
    distinct_count = bin(binary_chars**length_s).count('1')  # total number of distinct binary strings of length s

    @lru_cache(maxsize=None)
    def dp(inner_l, outer_l, outer_r, outer_s, outer_mask):
        if outer_l >= outer_r:
            return 0
        if outer_s > inner_l:
            return distinct_count - 2**outer_l
        mask = (1<<outer_s)-1 ^ outer_mask
        return (mask ^ outer_mask) * (1 + dp(inner_l, outer_l + inner_l, outer_r + inner_l, outer_s + inner_l, mask) for inner_l in range(length_s))

    return dp(n, 0, length_s, 0, 0)

