import sys

class ContactCounter(object):
    def __init__(self, population, k):
        self.population = population
        self.k = k
        self.current_contact_count = [-1] * population  # Initialize with -1 for not having contacted yet
        self.next_day_contacts = [0] * population  # Initialize contacts for next days

    def calculate_contacts(self, query_type, person, day):
        if query_type == 1:
            person_index = person - 1
            if self.next_day_contacts[person_index] == -1:
                self.current_contact_count[person_index] = 1
                for i in range(self.k):
                    day_index = (day + i) % self.population
                    if self.current_contact_count[day_index] == -1:
                        self.current_contact_count[day_index] = 0
                        for contact in self.next_day_contacts[day_index]:
                            if contact < person_index:
                                self.next_day_contacts[contact] += 1
        elif query_type == 2:
            contact_count = self.current_contact_count[person - 1]
            for i in range(self.k):
                self.current_contact_count[(day + i) % self.population] = contact_count
        elif query_type == 3:
            self.next_day_contacts[person - 1] = self.current_contact_count[person - 1]

