def find_cyclical_strings(s, n):
    def is_substring(t):
        if t in s: return 1
        return 0

    @lru_cache(None)
    def dp(i, l):
        if i == n:
            return 1
        return sum(dp(i+1, l) * is_substring(s[i+1:]) for l in range(len(s) + 1))

