import sys
from collections import deque

def dijkstra(graph, src, reverse_graph):
    dist = {node: float('inf') for node in graph}
    dist[src] = 0
    queue = deque([(0, src)])

    while queue:
        current_dist, current_node = queue.popleft()

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            if dist[neighbor] > current_dist + weight:
                dist[neighbor] = current_dist + weight
                queue.append((current_dist + weight, neighbor))

    for node, min_distance in dist.items():
        reverse_min_distance = reverse_graph[node].get(min_distance, float('inf'))
        if min_distance != reverse_min_distance:
            return False
    return True

