class QuerySystem:
    def __init__(self):
        self.a = []
        self.sizes = {}

    def add(self, ai, si=None):
        index = self.bin_search(ai)
        if si:
            if index in self.sizes:
                self.sizes[index] += [(si, ai)]
            else:
                self.sizes[index] = [(si, ai)]
        else:
            self.sizes[index] = [(ai, None)]

    def query(self, si):
        if self.sizes[si]:
            return sum(self.sizes[si])
        else:
            return 0

    def bin_search(self, ai):
        lo, hi = 0, len(self.a) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if self.a[mid] == ai:
                return mid
            elif self.a[mid] > ai:
                hi = mid - 1
            else:
                lo = mid + 1
        return lo

