from collections import Counter

def count_subsequences_with_sum(A, N, mod):
    memo = {}

    def dp(i, previous_sum):
        if i == N:
            return 0
        if i == 0:
            return 1
        if (i, previous_sum) in memo:
            return memo[(i, previous_sum)]

        if previous_sum != -A[i-1] and previous_sum != 1 + A[i-1]:
            excluded = 1 + dp(i-1, previous_sum) % mod
        else:
            excluded = 0

        included = previous_sum * 2 % mod

        result = (included + excluded) % mod

        memo[(i, previous_sum)] = result
        return result

