def generate_cyclic_strings(length):
    if length == 1:
        return ['0', '1']
    cyclic_strings = ['1' + x for x in generate_cyclic_strings(length - 1)]
    cyclic_strings = cyclic_strings + ['0' * length]
    return cyclic_strings

def count_cyclicstrings_with_k_maximal_substrings(k):
    n = len(k)
    if n <= 2:
        return max(1, n // 2)

    @lru_cache(None)
    def count(p, k_maximal, zeros):
        if p == n:
            return zeros
        diff = max(n - k_maximal, n - k % k_maximal, k + not k % 2)
        return (
            count(p + 1, k_maximal, zeros)
            + [total - count(p + 1, k_maximal, zeros)
               for total in count(p + 1, k * (n - k_maximal) % k, zeros)
               for diff in range(diff)]
        )

    zero_cycle_count = count(0, n // k, 0)
    one_cycle_count = 1 + sum((k % l) == 0 for l in range(2, n + 1, 2 if n % 2 == 0 else 1))

    rest_count = 0 if n % 2 == 0 else 1

    # This takes care of cases like "1010", which is not a prefix but can start in the middle
    if k % 2 == 0 and n // 2 not in k:
        rest_count += max(1, k // 2)

    return (one_cycle_count - zero_cycle_count) * (n - zero_cycle_count) + rest_count

