import heapq

def min_energy(x, k, n, q, c, sp):
    stones = [(c[i], i) for i in range(x)]
    heapq.heapify(stones)
    touching = [False] * n
    visited = [-1] * n
    visited[x - 1] = 0

    for i in range(n - x):
        for j in range(min(2, k - 1)):
            current, junction = heapq.heappop(stones)
            if touching[junction]:
                heapq.heappush(stones, (current, junction))
            else:
                for stone in range(junction + 1, junction + current + 1):
                    if (stone - junction) // current <= k:
                        touching[junction] = True
                        heapq.heapify(stones)
                        break

    for _ in range(q):
        p, wp = map(int, input().split())
        touching[p - 1] = True
        for j in range(min(2, k - 1)):
            if touching[j + x - 1]:
                wp = -wp
                heapq.heapify(stones)
                break

    touching.reverse()
    energy = sum(c[i] - wp + (k - i - sum(touching[:i])) * wp for i, c in enumerate(c))
    return energy

# Example usage
