# Calculate nCr using modulo operation
def mod_factorial(n, r):
    fact = [1]
    for i in range(1, n+1):
        fact.append((fact[-1] * i) % 1000000007)
    return fact[r]

# Calculate nCr! / n! using modulo operation
def mod_combination(n, r, p):
    return mod_factorial(n, r) * pow(num1, n - r, p) % p

# Function to calculate the number of possible sequences after j operations
def count_sequences(n, k, p):
    result = [1] * (k + 1)
    for j in range(2, k + 1):
        for start in range(1, min(j, n) + 1):
            for finish in range(start + 1, min(j + 1, n) + 1):
                prev_sequences = mod_combination(start - 1, finish - start, p)
                if finish < n:
                    next_sequences = mod_factorial(n - finish) * pow(num1, finish - n, p) % p
                else:
                    next_sequences = 0
                result[j] = (result[j] + mod_combination(n, j, p) * prev_sequences * (n - j) * pow(num1, j + 1, p) + next_sequences) % p
                num1 *= j
            num1 %= p
    return result

