To solve this problem, we need to determine the minimum number of hours Monocarp needs to obtain the $n$-th armor set and the $m$-th weapon. We can achieve this by simulating the process of obtaining new sets and weapons.

Here is a Python program that implements the solution:

```python
from collections import deque
from heapq import heappush, heappop

def find_min_hours(n, m, q, pairs):
    armor_set = list(range(1, n + 1))
    weapon = list(range(1, m + 1))
    queue = deque([(0, 1)])
    memo = {}

    for _, i in pairs:
        memo[(_ * 100) + i] = 'broken'

    while queue:
        cost, set_id = heappop(queue)
        if set_id == n and weapon[0] != i:
            return cost
        for i, j in pairs:
            if (i * 100) + j < -cost and i < m + 1 and j < n + 1:
                uphill_cost = -(i * 100 + j) - cost
                if memo[(i * 100) + j] == 'broken':
                    continue
                memo[(i * 100) + j] = 'broken'
                heappush(queue, (cost + uphill_cost, j))

                if set_id == 0:
                    # Initialize the set
                    for id in armor_set:
                        j = id
                        if product(id, j) >= uphill_cost:
                            heappush(queue, (cost + uphill_cost, j))
                            break

                elif j not in queue and len(queue[-1][1]) > 1:
                    heappush(queue, (cost + (100 * j) + m, j))

    return -1

def product(a, b):
    return a * b
