import math

def is_valid_triangle(x1, y1, x2, y2, x3, y3, n, S):
    area = abs((x1*(y2-y3) + x2*(y3-y1) + x3*(y1-y2)) / 2.0)
    return area <= 4*S

def construct_triangle(n, S, points):
    for i1 in range(n):
        for i2 in range(i1 + 1, n):
            x1, y1 = points[i1]
            x2, y2 = points[i2]
            for x3 in range(n):
                if x3 != i1 and x3 != i2:
                    x3, y3 = points[x3]
                    if is_valid_triangle(x1, y1, x2, y2, x3, y3, n, S):
                        return (x1, y1), (x2, y2), (x3, y3)
    return None

