def count_permutations(n, k):
    MOD = 10**9 + 7

    if k == 1:
        return [1] * n
    elif n == 2:
        return [2, 1]

    pre = [i for i in range(1, n)]
    main = [0] * (max(pre) + 1)

    main[0] = 1
    main[1] = 2
    main[2] = 1  # Considering swaps between 1st and 2nd cube

    for j in range(3, n):
        for i in range(1, j + 1):
            main[j] = (main[i] * main[j - i] + main[j] * main[j - 1]) % MOD

    def count_swaps(n, k):
        if k == 0:
            return 1
        else:
            return pre[k - 2] * main[n] % MOD

    result = [count_swaps(n, i - 1) for i in range(1, k + 1)]
    return result
