from itertools import permutations

def count_cyclical_strings(n, s):
    singles = set(s)
    multis = {''.join(p) for p in permutations(s)}

    def is_substring(s1, s2):
        return any(s2.startswith(t) for t in s1 if t != '')

    total_count = 0

    for mult in multis:
        has_sub = True
        for single in singles.copy():
            has_sub = has_sub and is_substring([mult + single], single)
            if len(single) < len(mult):
                singles.remove(single)
        if has_sub:
            total_count += 1

    return total_count

